def compute(vars):
    net_assets = vars["v2"]
    if net_assets == 0:
        return None
    portion = vars["v1"] / net_assets
    return {
        "value": portion,
        "trace": {
            "goodwill": vars["v1"],
            "net_assets_acquired": net_assets,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "ratio",
            },
        },
    }
